Signed-off-by: Thomas Hellström <thomas.hellstrom@linux.intel.com>

Here is the root cause:
ccs_mode_store() calls xe_gt_reset() which internally invokes xe_pm_runtime_get_noresume(), which requires the caller to already hold an outer runtime PM reference. The function lacked this reference, causing a warning about missing runtime PM protection.

Here is the patch:
 #include "xe_gt_sysfs.h"
 #include "xe_mmio.h"
+#include "xe_pm.h"
 #include "xe_sriov.h"


 static ssize_t
 ccs_mode_store(struct device *kdev, struct device_attribute *attr,
 	       const char *buff, size_t count)
 {
 	struct xe_gt *gt = kobj_to_gt(&kdev->kobj);
 	struct xe_device *xe = gt_to_xe(gt);
 	u32 num_engines, num_slices;
 	int ret;

 	if (IS_SRIOV(xe)) {
 		xe_gt_dbg(gt, "Can't change compute mode when running as %s\n",
 			  xe_sriov_mode_to_string(xe_device_sriov_mode(xe)));
 		return -EOPNOTSUPP;
 	}

 	ret = kstrtou32(buff, 0, &num_engines);
 	if (ret)
 		return ret;

 	/*
 	 * Ensure number of engines specified is valid and there is an
 	 * exact multiple of engines for slices.
 	 */
 	num_slices = hweight32(CCS_INSTANCES(gt));
 	if (!num_engines || num_engines > num_slices || num_slices % num_engines) {
 		xe_gt_dbg(gt, "Invalid compute config, %d engines %d slices\n",
 			  num_engines, num_slices);
 		return -EINVAL;
 	}

 	/* CCS mode can only be updated when there are no drm clients */
 	mutex_lock(&xe->drm.filelist_mutex);
 	if (!list_empty(&xe->drm.filelist)) {
 		mutex_unlock(&xe->drm.filelist_mutex);
 		xe_gt_dbg(gt, "Rejecting compute mode change as there are active drm clients\n");
 		return -EBUSY;
 	}

 	if (gt->ccs_mode != num_engines) {
 		xe_gt_info(gt, "Setting compute mode to %d\n", num_engines);
 		gt->ccs_mode = num_engines;
 		xe_gt_record_user_engines(gt);
+		guard(xe_pm_runtime)(xe);
 		xe_gt_reset(gt);
 	}

 	mutex_unlock(&xe->drm.filelist_mutex);

 	return count;
 }



